    /// A section's changes of several commands, the tone equalizer's release of its bands and
    /// its reset of them, go as one `Step { source: You }`, one history step, each change
    /// shown as it would be alone.
    #[test]
    fn changes_of_several_commands_are_sent_as_one_step() {
        let set = |control, value| Change::Set {
            tool: "toneequal",
            control,
            value: ControlValue::Number(value),
            done: true,
        };
        let reset = |control| Change::Reset {
            tool: "toneequal",
            control,
        };
        let changes = vec![set("shadows", 0.5), set("blacks", 0.25), reset("noise")];
        let alone: Vec<_> = changes.iter().cloned().map(|c| sent(c).unwrap()).collect();
        let (command, shown) = sent(Change::Step(changes)).unwrap();
        let (commands, each): (Vec<_>, Vec<_>) = alone.into_iter().unzip();
        assert!(matches!(commands[2], Command::ResetControl { .. }));
        assert_eq!(
            command,
            Command::Step {
                source: StepSource::You,
                note: None,
                commands,
            }
        );
        assert_eq!(shown, each.concat());
        assert_eq!(shown.len(), 3);
        // It completes a change, which the save state waits for; a `Step` of a gesture's
        // changes alone does not, as the engine says.
        assert!(completes(&command));
        let dragged = Change::Set {
            tool: "toneequal",
            control: "shadows",
            value: ControlValue::Number(0.5),
            done: false,
        };
        let (gesture, _) = sent(Change::Step(vec![dragged])).unwrap();
        assert!(!completes(&gesture));
    }

    #[test]
    fn changes_shown_as_they_are_sent_show_what_the_session_s_edit_will_report() {
        use apertrust_engine::edit::{self, Edit, Held};
        use apertrust_engine::session::{ControlState, CoordinateState, ToolState};
        use apertrust_tools::testing::{self, Twin};

        /// A change to Twin, through a control's row or a coordinate's.
        #[derive(Debug, Clone, Copy, PartialEq)]
        enum Step {
            Set(&'static str, f32),
            Reset(&'static str),
            Keep(&'static str, bool),
            ResetTool,
        }

        let image = testing::image();
        let tools: &[&dyn ProcessingTool] = &[&Twin];
        let definition = Twin.definition();
        let coordinate = |id| definition.coordinate(id).is_some();
        // What the session reports of Twin with `edit` and `held`: each control's value
        // over its default and its mark, each view's coordinates, held or the tool's
        // view of the values, with the mark its controls share.
        let report = |edit: &Edit, held: &Held| {
            let set = edit.tool("twin");
            let defaults = Twin.defaults(&image);
            let controls: Vec<ControlState> = definition
                .controls
                .iter()
                .map(|control| {
                    let default = defaults.get(control.id).unwrap().clone();
                    let value = set.and_then(|v| v.get(control.id)).cloned();
                    ControlState {
                        control: control.id,
                        value: value.unwrap_or_else(|| default.clone()),
                        default,
                        mark: set.and_then(|v| v.mark(control.id)),
                        available: true,
                        options: Vec::new(),
                        range: None,
                        visible: true,
                        label_value: None,
                    }
                })
                .collect();
            let mut views = Vec::new();
            for view in definition.views {
                let values = edit.coordinates(held, &Twin, view, &image).unwrap();
                let defaults = edit::default_coordinates(&Twin, view, &image).unwrap();
                let marks: Vec<_> = view
                    .controls
                    .iter()
                    .map(|c| set.and_then(|v| v.mark(c)))
                    .collect();
                let mark = marks[0].filter(|_| marks.iter().all(|m| *m == marks[0]));
                let each = view.coordinates.iter().zip(values).zip(defaults);
                views.extend(each.map(|((c, value), default)| CoordinateState {
                    view: view.id,
                    coordinate: c.id,
                    value,
                    default,
                    mark,
                    available: true,
                }));
            }
            let edited = controls.iter().any(|c| c.value != c.default);
            Values {
                tools: vec![ToolState {
                    tool: "twin",
                    enabled: true,
                    edited,
                    hidden: false,
                    controls,
                    presets: Vec::new(),
                    views,
                    computed: Vec::new(),
                }],
                settings: Vec::new(),
                edited,
                through: 0,
                extent: [84, 62],
                live: true,
            }
        };
        // The step on the session's edit, its holds then pruned as after every change.
        let apply = |edit: &mut Edit, held: &mut Held, step: Step| {
            let number = ControlValue::Number;
            let done = match step {
                Step::Set(id, v) if coordinate(id) => {
                    edit.set_coordinate(held, &Twin, id, number(v), &image)
                }
                Step::Set(id, v) => edit.set_control(&Twin, id, number(v), &image),
                Step::Reset(id) if coordinate(id) => edit.reset_coordinate(held, &Twin, id, &image),
                Step::Reset(id) => edit.reset_control(&Twin, id),
                Step::Keep(id, kept) if coordinate(id) => edit.keep_coordinate(&Twin, id, kept),
                Step::Keep(id, kept) => edit.keep(&Twin, id, kept),
                Step::ResetTool => {
                    edit.reset_tool(&Twin);
                    Ok(())
                }
            };
            done.unwrap();
            held.prune(edit);
        };
        // The step as the app sends it.
        let pending = |step: Step| {
            let tool = "twin";
            match step {
                Step::Set(control, v) => Pending::Control {
                    tool,
                    control,
                    value: ControlValue::Number(v),
                },
                Step::Reset(control) => Pending::Reset { tool, control },
                Step::Keep(control, kept) => Pending::Keep {
                    tool,
                    control,
                    kept,
                },
                Step::ResetTool => Pending::ResetTool { tool },
            }
        };
        // x through its own row, then the pair, then the mix, which moves the pair, and
        // back: a coordinate reset with the other held, released and kept, x reset, both
        // of the pair's back, which resets x and y and moves the mix, then the tool.
        let steps = [
            Step::Set("x", 30.0),
            Step::Set("sum", 110.0),
            Step::Set("sum", 111.0),
            Step::Set("u", 200.0),
            Step::Set("v", 12.0),
            Step::Reset("difference"),
            Step::Keep("sum", false),
            Step::Keep("u", true),
            Step::Reset("x"),
            Step::Reset("sum"),
            Step::Reset("difference"),
            Step::Set("u", 150.0),
            Step::ResetTool,
        ];
        let (mut edit, mut held) = (Edit::default(), Held::default());
        // As `App::pend` shows each change once over the values as they are; and as it
        // did before, showing every pending change again over values that held them.
        let mut sent = report(&edit, &held);
        let (mut again, mut every) = (sent.clone(), Vec::new());
        let mut wrong = None;
        for (number, step) in (1..).zip(steps) {
            apply(&mut edit, &mut held, step);
            let expected = report(&edit, &held);
            let change = pending(step);
            show(&mut sent, &change, tools, &image);
            assert_eq!(sent.tools, expected.tools, "after {step:?}");
            every.push((number, change));
            again = reported(again, &mut every, tools, &image);
            if wrong.is_none() && again.tools != expected.tools {
                wrong = Some(step);
            }
        }
        // Showing them again starts the second step of the sum from where showing x
        // again moved the pair.
        assert_eq!(wrong, Some(Step::Set("sum", 111.0)));
    }

    /// White balance's temperature and tint read the camera's matrix (decision 27): a
    /// drag shows the coefficients the session will write, through the image context the
    /// session's `Photo` carries, not the sRGB matrix a photo's size alone would give.
    #[test]
    fn a_temperature_dragged_shows_the_coefficients_the_camera_s_matrix_gives() {
        use apertrust_engine::session::{ControlState, CoordinateState, ToolState};
        use apertrust_tools::testing;
        use apertrust_tools::white_balance::{COEFFICIENTS, WhiteBalance};

        // The synthetic raw with a Canon EOS 40D's matrix, far from sRGB's.
        let mut image = testing::image();
        let matrix = [
            [6071.0, -747.0, -856.0],
            [-7653.0, 15365.0, 2441.0],
            [-2025.0, 2553.0, 7315.0],
        ];
        image.camera.as_mut().unwrap().xyz_to_camera =
            Some(matrix.map(|row: [f32; 3]| row.map(|v| v / 10000.0)));
        let photo = PhotoState::Open(Photo {
            path: PathBuf::from("40D.CR2"),
            open: 1,
            camera: String::new(),
            width: 84,
            height: 62,
            view_only: None,
            exposure_time: None,
            aperture: None,
            focal_length: None,
            image: Box::new(image.clone()),
        });
        assert_eq!(photo.image(), image);

        // White balance at its defaults, as the session reports it.
        let definition = WhiteBalance.definition();
        let defaults = WhiteBalance.defaults(&image);
        let view = &definition.views[0];
        let viewed = WhiteBalance.view(view.id, &defaults, &image).unwrap();
        let report = Values {
            tools: vec![ToolState {
                tool: definition.tool.id,
                enabled: true,
                edited: false,
                hidden: false,
                controls: definition
                    .controls
                    .iter()
                    .map(|control| {
                        let value = defaults.get(control.id).unwrap().clone();
                        ControlState {
                            control: control.id,
                            value: value.clone(),
                            default: value,
                            mark: None,
                            available: true,
                            options: Vec::new(),
                            range: None,
                            visible: true,
                            label_value: None,
                        }
                    })
                    .collect(),
                presets: Vec::new(),
                views: view
                    .coordinates
                    .iter()
                    .zip(&viewed)
                    .map(|(coordinate, &value)| CoordinateState {
                        view: view.id,
                        coordinate: coordinate.id,
                        value,
                        default: value,
                        mark: None,
                        available: true,
                    })
                    .collect(),
                computed: Vec::new(),
            }],
            settings: Vec::new(),
            edited: false,
            through: 0,
            extent: [84, 62],
            live: true,
        };
        let tools: &[&dyn ProcessingTool] = &[&WhiteBalance];
        let drag = Pending::Control {
            tool: definition.tool.id,
            control: "temperature",
            value: ControlValue::Number(5000.0),
        };
        let shown = |image: &ImageContext| {
            let mut values = report.clone();
            show(&mut values, &drag, tools, image);
            let controls = &values.tools[0].controls;
            COEFFICIENTS.map(|id| {
                let shown = controls.iter().find(|c| c.control == id).unwrap();
                (shown.value.clone(), shown.mark)
            })
        };
        let expected = WhiteBalance
            .unview(view.id, &[5000.0, viewed[1]], &image)
            .unwrap();
        let through_the_camera = shown(&photo.image());
        for (id, (value, mark)) in COEFFICIENTS.iter().zip(&through_the_camera) {
            assert_eq!((Some(value), *mark), (expected.get(id), Some(Mark::Kept)));
        }
        // The photo's size alone reads the coefficients through sRGB's matrix instead.
        assert_ne!(through_the_camera, shown(&ImageContext::full(84, 62)));
    }

    /// What Settings' window hands the app, the setting `id` set to `value`, kept by
    /// `keeper` and shown by `shell` in `ctx`'s window, as `App::logic` takes it.
    fn set_in_settings(
        shell: &mut Shell,
        keeper: &mut Keeper,
        id: &'static str,
        value: impl Into<toml::Value>,
        ctx: &egui::Context,
    ) {
        let change = settings_dialog::Change::Set(id, value.into());
        apply_settings(&[change], shell, keeper, ctx);
    }

    /// What Settings changes reaches the shell, which keeps it, and the main window, which
    /// shows it at once; the dialog's own drawing is the dialog's (`settings_dialog::tests`)
    /// and the host's (`dialog_host::tests`), on every platform.
    #[test]
    fn settings_change_the_theme_and_the_language_at_once() {
        let (mut keeper, settings) = Keeper::nowhere();
        let mut shell = Shell::new(&settings, Locale::EnGb, OperatingSystem::Windows);
        let ctx = egui::Context::default();
        apertrust_ui::install(&ctx, Theme::default());
        set_in_settings(&mut shell, &mut keeper, "theme", "light", &ctx);
        assert_eq!(shell.theme, Builtin::Light);
        assert_eq!(theme(&ctx).colors, Theme::builtin(Builtin::Light).colors);
        set_in_settings(&mut shell, &mut keeper, "locale", "uk", &ctx);
        assert_eq!(
            (shell.locale, shell.kept_locale),
            (Locale::Uk, Some(Locale::Uk))
        );
        assert_eq!(apertrust_ui::translator(&ctx).locale(), Locale::Uk);
        // Reset, the language follows the system's again.
        let reset = settings_dialog::Change::Reset("locale");
        apply_settings(&[reset], &mut shell, &mut keeper, &ctx);
        assert_eq!((shell.locale, shell.kept_locale), (Locale::EnGb, None));
        // The dialog it opens shows what is kept.
        let view = settings_dialog::Settings::new(&keeper, true);
        let theme = view.row("theme").expect("the theme's row");
        assert_eq!(theme.value, Some("light".into()));
        assert!(theme.changed());
    }

    /// A row `--conf` sets for this run is handed to the dialog as overridden, which draws
    /// it disabled, saying why (decision 43; drawn in `settings_dialog::tests`), and the
    /// run keeps the value it gives.
    #[test]
    fn settings_set_by_conf_are_drawn_disabled_saying_why() {
        let overrides = settings::overrides(&["theme=light".to_owned(), "locale=pl".to_owned()]);
        let (keeper, settings) = Keeper::open_in(None, &overrides.expect("read"));
        let shell = Shell::new(&settings, Locale::EnGb, OperatingSystem::Windows);
        assert_eq!((shell.theme, shell.locale), (Builtin::Light, Locale::Pl));
        let view = settings_dialog::Settings::new(&keeper, true);
        let overridden: Vec<&str> = view
            .rows
            .iter()
            .filter(|row| row.overridden)
            .map(|row| row.id)
            .collect();
        assert_eq!(overridden, ["theme", "locale"]);
        // In each language, with the flag as it is typed.
        for (locale, words) in [
            (Locale::Uk, "Задано через --conf для цього запуску"),
            (Locale::Pl, "Ustawione przez --conf na to uruchomienie"),
        ] {
            let mut args = apertrust_ui::i18n::Args::new();
            args.set("flag", CONF_FLAG);
            let said = Translator::new(locale).text_with("settings-overridden", Some(&args));
            assert_eq!(said, words);
        }
    }

    fn read(line: &[&str]) -> Result<Arguments, String> {
        arguments(line.iter().map(OsString::from))
    }

    /// `photo.ARW`, as the command line gives it: from the folder the app starts in.
    fn photo_arw() -> Vec<PathBuf> {
        vec![std::path::absolute("photo.ARW").expect("absolute")]
    }

    /// Every path given, absolute, wherever it comes among the flags, which are read as
    /// ever around them. The disk is never asked here: what each is, a folder, a raw, an
    /// edit, a library's file or nothing there, is looked at once the window is up, as a
    /// drop's is (`dropped::Drops::look_given`). With none, nothing is given.
    #[test]
    fn the_command_line_s_paths_are_kept_whole_and_the_disk_never_asked() {
        let absolute = |path: &str| std::path::absolute(path).expect("absolute");
        assert_eq!(read(&["photo.ARW"]).expect("read").paths, photo_arw());
        let line = [
            "--conf",
            "scale=2",
            "Trips/Lisbon",
            "-d",
            "settings",
            "/a/IMG_2.CR3.apxmp",
            "--cache-dir=one",
            "/nowhere/Home.aplibrary",
        ];
        let given = read(&line).expect("read");
        assert_eq!(
            given.paths,
            [
                absolute("Trips/Lisbon"),
                absolute("/a/IMG_2.CR3.apxmp"),
                absolute("/nowhere/Home.aplibrary")
            ]
        );
        assert_eq!(given.conf, ["scale=2"]);
        assert_eq!(given.domains, ["settings"]);
        assert!(given.cache.is_some());
        assert!(read(&["-d", "gpu"]).expect("read").paths.is_empty());
    }

    /// A second start's paths are taken from its own working folder, never the instance's
    /// (decision 89); its absolute ones as they are.
    #[test]
    fn a_second_start_s_paths_are_taken_from_its_folder() {
        let folder = std::path::absolute("elsewhere").expect("absolute");
        let line = ["Trips/IMG_1.ARW", "-d", "gpu", "/a/IMG_2.CR3"].map(OsString::from);
        let given = arguments_in(line, Some(&folder)).expect("read");
        let absolute = |path: &str| std::path::absolute(path).expect("absolute");
        assert_eq!(
            given.paths,
            [folder.join("Trips/IMG_1.ARW"), absolute("/a/IMG_2.CR3")]
        );
    }

    /// A second start whose working folder could not be read hands over none: its relative
    /// paths are dropped rather than taken from the instance's folder, its absolute ones
    /// taken.
    #[test]
    fn a_relative_path_with_no_sender_folder_is_dropped() {
        let absolute = std::path::absolute("IMG_2.CR3").expect("absolute");
        let line = [
            OsString::from("IMG_1.ARW"),
            absolute.clone().into_os_string(),
        ];
        let given = arguments_in(line, Some(Path::new(""))).expect("read");
        assert_eq!(given.paths, [absolute]);
    }

    /// A second start hands over its paths already absolute, from its own folder, with its
    /// flags, so the instance reads the same command line wherever its own folder is; on
    /// Windows a drive-relative path is the second start's drive's.
    #[test]
    fn a_second_start_hands_over_its_paths_absolute() {
        let line = [
            "-d",
            "gpu",
            "Trips/IMG_1.ARW",
            "--safe-mode",
            "--conf=scale=2",
        ];
        let given = read(&line).expect("read");
        let sent = handed(&given.flags, given.safe_mode, &given.paths);
        let elsewhere = std::path::absolute("elsewhere").expect("absolute");
        let taken = arguments_in(sent, Some(&elsewhere)).expect("read");
        assert_eq!(
            taken.paths,
            [std::path::absolute("Trips/IMG_1.ARW").expect("absolute")]
        );
        assert_eq!(
            (taken.domains, taken.conf, taken.safe_mode),
            (given.domains, given.conf, true)
        );
        #[cfg(windows)]
        {
            let drive = read(&["C:IMG_1.ARW"]).expect("read");
            let sent = handed(&drive.flags, drive.safe_mode, &drive.paths);
            let taken = arguments_in(sent, Some(Path::new(r"D:\elsewhere"))).expect("read");
            assert_eq!(taken.paths, drive.paths);
            assert!(taken.paths[0].is_absolute(), "{:?}", taken.paths);
        }
        let trailing = read(&["IMG_1.ARW", "-d"]).expect("read");
        let sent = handed(&trailing.flags, trailing.safe_mode, &trailing.paths);
        let taken = arguments_in(sent, Some(&elsewhere)).expect("read");
        assert_eq!(taken.paths, trailing.paths);
        assert!(taken.domains.is_empty(), "{:?}", taken.domains);
    }

    /// The flags for one run a second start hands over: `--safe-mode`, each domain and each
    /// `--conf`, as typed; none for a start given only paths and folders.
    #[test]
    fn a_second_start_hands_over_its_flags_for_one_run() {
        let given = read(&[
            "--debug",
            "gpu",
            "photo.ARW",
            "--conf=scale=2",
            "--safe-mode",
            "--user-data-dir",
            "dev",
            "--cache-dir",
            "cache",
        ])
        .expect("read");
        let flags = one_run(&given.domains, &given.conf, given.safe_mode);
        assert_eq!(
            instance::flags_line(&flags),
            "--safe-mode -d gpu --conf scale=2"
        );
        let plain = read(&["photo.ARW", "--user-data-dir", "dev"]).expect("read");
        assert!(one_run(&plain.domains, &plain.conf, plain.safe_mode).is_empty());
    }

    /// The instance takes a second start's paths, from its working folder, and posts them
    /// to the window with its token; one with flags for one run is refused, and the window
    /// told, to raise its alert.
    #[test]
    fn the_instance_takes_a_second_start_or_refuses_it() {
        let (post, inbox) = instance::mailbox();
        let cache = PathBuf::from("/cache");
        let handler = hand_offs(post, cache.clone(), "/user-data".into(), Instant::now());
        let token = instance::Token {
            wayland: Some("token".into()),
            x11: None,
        };
        let taken = instance::HandOff {
            arguments: vec!["IMG_1.ARW".into()],
            folder: std::path::absolute("trip").expect("absolute"),
            token: token.clone(),
            cache: Some(cache),
            ..instance::HandOff::default()
        };
        assert_eq!(handler(taken.clone()), instance::Answer::Taken);
        let arrived = inbox.take();
        let [
            instance::Arrival::Open {
                paths,
                token: given,
                ..
            },
        ] = &arrived[..]
        else {
            panic!("not posted: {arrived:?}");
        };
        assert_eq!(paths, &[taken.folder.join("IMG_1.ARW")]);
        assert_eq!(given, &token);
        let refused = instance::HandOff {
            one_run: vec!["--safe-mode".into()],
            ..taken
        };
        let instance::Answer::Refused(why) = handler(refused) else {
            panic!("taken");
        };
        assert!(
            why.contains("/user-data") && why.contains("--safe-mode"),
            "{why}"
        );
        let arrived = inbox.take();
        let [instance::Arrival::Refused { flags, .. }] = &arrived[..] else {
            panic!("not posted: {arrived:?}");
        };
        assert_eq!(flags, &[OsString::from("--safe-mode")]);
        // Once the window's inbox has closed, as the app commits to quitting, or gone,
        // nothing is taken that cannot open.
        let _ = inbox.close();
        let late = instance::HandOff {
            arguments: vec!["IMG_2.ARW".into()],
            ..instance::HandOff::default()
        };
        let instance::Answer::Refused(why) = handler(late) else {
            panic!("taken with no window to open it");
        };
        assert!(why.contains("quitting"), "{why}");
    }

    /// Refused starts' alerts come one at a time, in order: one that finds an alert up waits
    /// for the next turn rather than being lost; one that cannot be shown is done.
    #[test]
    fn refused_starts_alerts_wait_their_turn() {
        use dialog_host::Ask;
        let mut waiting = VecDeque::from(["first", "second", "third"]);
        let mut asked = Vec::new();
        let mut up = false;
        raise_in_turn(&mut waiting, |flags| {
            if up {
                return Ask::Busy;
            }
            asked.push(*flags);
            up = true;
            Ask::Shown
        });
        assert_eq!(asked, ["first"]);
        assert_eq!(waiting, ["second", "third"]);
        // The first answered: the second is shown, the third failing is done with.
        let mut answers = vec![Ask::Shown, Ask::Failed].into_iter();
        raise_in_turn(&mut waiting, |_| answers.next().unwrap());
        assert!(waiting.is_empty());
    }

    /// The window comes forward with the latest token handed over while it started, one
    /// with none never taking its place.
    #[test]
    fn the_latest_token_brings_the_window_forward() {
        let wayland = |token: &str| instance::Token {
            wayland: Some(token.into()),
            x11: None,
        };
        let mut kept = None;
        keep_forward(&mut kept, instance::Token::default());
        assert_eq!(kept, Some(instance::Token::default()));
        keep_forward(&mut kept, wayland("first"));
        keep_forward(&mut kept, instance::Token::default());
        assert_eq!(kept, Some(wayland("first")));
        keep_forward(&mut kept, wayland("second"));
        assert_eq!(kept, Some(wayland("second")));
    }

    /// The alert a refused start raises names its flags, in every language.
