    /// Find Tool…'s field in the tab bar's place, empty, with tools found, and with
    /// nothing matching, in the dark and light themes, at the Tools panel's 320 points: the
    /// Default workspace, and Essentials for a hidden tool found (decision 96).
    #[test]
    fn find_tool_s_field_and_the_tools_found() {
        let mut results = egui_kittest::SnapshotResults::new();
        let cases = [
            ("empty", "", layout::DEFAULT),
            ("found", "colour", layout::DEFAULT),
            ("hidden", "output", layout::ESSENTIALS),
            ("none", "xyz", layout::DEFAULT),
        ];
        for (which, name) in [(Builtin::Dark, "dark"), (Builtin::Light, "light")] {
            for (what, typed, workspace) in cases {
                let folder = settings::testing::Folder::new("find-tool-snapshot");
                let mut harness = find_panel(&folder, egui::vec2(320.0, 220.0), which);
                let (workspace, _) = layout::Workspaces::builtin().open(workspace);
                harness.state_mut().shell.open_workspace(workspace);
                harness.state_mut().shell.toggle_find();
                harness.run();
                if !typed.is_empty() {
                    find_field(&harness).type_text(typed);
                }
                harness.run();
                harness.snapshot(format!("find-tool-{what}-{name}"));
                results.extend(harness.take_snapshot_results());
            }
        }
    }

    /// Every tool's values as the session reports them for a photo, every control live,
    /// Exposure's at `exposure`, after `through` commands.
    fn photo_values(exposure: f32, through: u64) -> Values {
        let mut values = crate::mirror::tests::mirror().values;
        for state in &mut values.tools {
            for control in &mut state.controls {
                control.available = true;
                if (state.tool, control.control) == ("exposure", "exposure") {
                    control.value = ControlValue::Number(exposure);
                }
            }
        }
        values.through = through;
        values.live = true;
        values
    }

    /// A photo opening shows its values read-only until it is live (decision 77): every
    /// control disabled, its tooltip saying why, Scopes with no graph; live, enabled in
    /// the next frame.
    #[test]
    fn a_photo_opening_shows_its_values_disabled_until_it_is_live() {
        use crate::mirror::tests::photo;
        let folder = settings::testing::Folder::new("panel-opening");
        let mut harness = editing(&folder);
        let mirror = &mut harness.state_mut().mirror;
        mirror.opening(PathBuf::from("IMG_2041.ARW"), 2, Instant::now());
        mirror.apply(Event::Opened(Photo {
            path: PathBuf::from("IMG_2041.ARW"),
            ..photo(2)
        }));
        mirror.apply(Event::Values(Values {
            live: false,
            ..photo_values(1.5, 3)
        }));
        harness.run();
        assert_eq!(exposure_slider(&harness), (String::from("+1.500 EV"), true));
        assert_eq!(graph_says_in(&harness, "Histogram"), "Nothing measured yet");
        // Its tooltip says why.
        harness
            .get_by_role_and_label(Role::Slider, "Exposure")
            .hover();
        // A second's frames, past egui's tooltip delay.
        for _ in 0..60 {
            harness.step();
        }
        let tip = "Opening IMG_2041…";
        assert!(harness.query_by_role_and_label(Role::Label, tip).is_some());
        // Screen readers hear it on each row of controls.
        let described = harness
            .query_all_by_role(Role::Group)
            .filter(|row| row.accesskit_node().description().as_deref() == Some(tip))
            .count();
        assert!(described > 1, "{described}");
        // Live: enabled, and nothing said of opening.
        harness
            .state_mut()
            .mirror
            .apply(Event::Values(photo_values(1.5, 3)));
        harness.run();
        assert_eq!(
            exposure_slider(&harness),
            (String::from("+1.500 EV"), false)
        );
        let described = harness
            .query_all_by_role(Role::Group)
            .filter(|row| row.accesskit_node().description().as_deref() == Some(tip))
            .count();
        assert_eq!(described, 0);
    }

    /// A photo opening as the app draws it, for the snapshots: the viewer bar, Rendering…
    /// on it from `rendering`, the picture fitted in the photo's slot, and the Tools
    /// panel's Adjust tab with the photo's values read-only.
    struct Opening {
        shell: Shell,
        mirror: Mirror,
        rendering: Instant,
        picture: Option<(u64, egui::TextureHandle)>,
    }

    fn opening_scene(folder: &settings::testing::Folder) -> Harness<'static, Opening> {
        use crate::mirror::tests::photo;
        let (_, settings) = Keeper::open(folder.storage());
        let mut mirror = crate::mirror::tests::mirror();
        let asked = Instant::now();
        mirror.opening(PathBuf::from("IMG_2041.ARW"), 2, asked);
        // The camera's picture: a gradient, sky over ground.
        let (width, height) = (300, 200);
        let pixels: Vec<u8> = (0..width * height)
            .flat_map(|i| {
                let (x, y) = (i % width, i / width);
                let sky = y < height * 3 / 5;
                let shade = (x * 120 / width) as u8;
                if sky {
                    [90 + shade / 2, 140 + shade / 3, 200, 255]
                } else {
                    [70 + shade / 3, 110, 60 + shade / 4, 255]
                }
            })
            .collect();
        mirror.apply(Event::OpenPreview(apertrust_engine::session::OpenPreview {
            open: 2,
            picture: Some(apertrust_engine::session::library::Thumbnail {
                width,
                height,
                pixels: pixels.into(),
            }),
            source: apertrust_engine::session::PreviewSource::Embedded,
        }));
        mirror.apply(Event::Opened(Photo {
            path: PathBuf::from("IMG_2041.ARW"),
            ..photo(2)
        }));
        mirror.apply(Event::Values(Values {
            live: false,
            // Its edit crops it square: the 3:2 picture letterboxed in the square place.
            extent: [600, 600],
            ..photo_values(1.5, 3)
        }));
        Harness::builder()
            .with_size(egui::vec2(1000.0, 640.0))
            .with_context_setup(|ctx| apertrust_ui::install(ctx, Theme::default()))
            .build_ui_state(
                |ui, scene: &mut Opening| {
                    let t = theme(ui.ctx());
                    let full = ui.max_rect();
                    let side = egui::Rect::from_min_max(
                        egui::pos2(full.right() - 360.0, full.top()),
                        full.max,
                    );
                    let centre =
                        egui::Rect::from_min_max(full.min, egui::pos2(side.left(), full.bottom()));
                    ui.painter()
                        .rect_filled(centre, 0.0, t.colors.photo_surround);
                    ui.painter().rect_filled(side, 0.0, t.colors.panel);
                    let now = scene.rendering;
                    ui.scope_builder(egui::UiBuilder::new().max_rect(centre), |ui| {
                        let rendering = scene
                            .mirror
                            .rendering(now)
                            .then(|| tr(ui.ctx(), "photo-rendering"));
                        let layer = tr(ui.ctx(), "layer-image");
                        ViewerBar::new(&layer, Zoom::Fit)
                            .toggles(
                                Toggle::new(false, false),
                                Toggle::new(false, false),
                                Toggle::new(false, false),
                                Toggle::new(false, false),
                            )
                            .status(rendering.as_deref())
                            .show(ui);
                        let slot = egui::Rect::from_min_max(ui.cursor().min, centre.max);
                        let block = PhotoFrame::new(slot, Margin::Points(24.0));
                        let ppp = ui.pixels_per_point();
                        let room = block.bounds();
                        let bounds = ((room.x * ppp) as u32, (room.y * ppp) as u32);
                        // As `App::viewer` places and draws it.
                        let (picture, generation) = scene.mirror.picture().expect("the picture");
                        let values = Some(&scene.mirror.values);
                        let fit = zoom::Zoomed::FIT;
                        let placed = place_photo(&block, bounds, ppp, &fit, values, Some(picture))
                            .expect("a place");
                        let painter = ui.painter_at(slot);
                        paint_picture(&painter, &placed, picture, generation, &mut scene.picture);
                    });
                    ui.scope_builder(egui::UiBuilder::new().max_rect(side), |ui| {
                        ui.spacing_mut().item_spacing.y = 0.0;
                        let panels = tools::Panels::default();
                        let (shell, mirror) = (&scene.shell, &scene.mirror);
                        let (settings, state) = editing_state(ui.ctx(), shell, mirror);
                        edit_tab(
                            ui,
                            shell,
                            mirror,
                            &settings,
                            &state,
                            &panels,
                            false,
                            &mut |_, _, _| {},
                        );
                    });
                },
                Opening {
                    shell: tools_opened(Shell::new(&settings, Locale::EnGb, OperatingSystem::Mac)),
                    mirror,
                    rendering: asked,
                    picture: None,
                },
            )
    }

    /// The Viewer showing a photo's picture while it opens, its controls disabled,
    /// with no Rendering… before a second, then with it (decision 77). Look at them.
    #[test]
    fn a_photo_opening_shows_its_picture_unmarked_then_rendering() {
        let folder = settings::testing::Folder::new("opening-scene");
        let mut harness = opening_scene(&folder);
        harness.run();
        assert!(harness.query_by_label("Rendering…").is_none());
        assert_eq!(exposure_slider(&harness), (String::from("+1.500 EV"), true));
        harness.snapshot("opening-picture");
        let later = harness.state().rendering + mirror::RENDERING_AFTER;
        harness.state_mut().rendering = later;
        harness.run();
        assert!(harness.query_by_label("Rendering…").is_some());
        harness.snapshot("opening-rendering");
    }

    /// A photo's slot as the Viewer places and draws it while the photo opens, its
    /// picture's rectangle and the photo's place kept from the last frame.
    struct Places {
        mirror: Mirror,
        picture: Option<(u64, egui::TextureHandle)>,
        drawn: Option<egui::Rect>,
        placed: Option<Placed>,
    }

    /// A slot at twice the scale whose room is 1800 pixels wide, with a photo opening whose
    /// picture, `width` by `height`, has come and nothing else.
    fn places_scene(width: u32, height: u32) -> Harness<'static, Places> {
        let mut mirror = crate::mirror::tests::mirror();
        mirror.opening(PathBuf::from("IMG_2041.ARW"), 2, Instant::now());
        mirror.apply(Event::OpenPreview(apertrust_engine::session::OpenPreview {
            open: 2,
            picture: Some(apertrust_engine::session::library::Thumbnail {
                width,
                height,
                pixels: vec![128; (width * height * 4) as usize].into(),
            }),
            source: apertrust_engine::session::PreviewSource::Embedded,
        }));
        Harness::builder()
            .with_size(egui::vec2(964.0, 1000.0))
            .with_pixels_per_point(2.0)
            .build_ui_state(
                |ui, scene: &mut Places| {
                    // As `App::viewer` places and draws it.
                    let slot = ui.max_rect();
                    let block = PhotoFrame::new(slot, Margin::Points(24.0));
                    let ppp = ui.pixels_per_point();
                    let room = block.bounds();
                    let bounds = ((room.x * ppp).floor() as u32, (room.y * ppp).floor() as u32);
                    let open = matches!(scene.mirror.photo, PhotoState::Open(_));
                    let values = open.then_some(&scene.mirror.values);
                    let picture = scene.mirror.picture();
                    scene.placed = place_photo(
                        &block,
                        bounds,
                        ppp,
                        &zoom::Zoomed::FIT,
                        values,
                        picture.map(|(p, _)| p),
                    );
                    let painter = ui.painter_at(slot);
                    scene.drawn = match (picture, &scene.placed) {
                        (Some((shown, generation)), Some(placed)) => Some(paint_picture(
                            &painter,
                            placed,
                            shown,
                            generation,
                            &mut scene.picture,
                        )),
                        _ => None,
                    };
                },
                Places {
                    mirror,
                    picture: None,
                    drawn: None,
                    placed: None,
                },
            )
    }

    /// The photo's place, and where its picture was drawn, in the last frame.
    fn places(harness: &Harness<'_, Places>) -> (egui::Rect, Option<egui::Rect>) {
        let scene = harness.state();
        (scene.placed.expect("a place").photo, scene.drawn)
    }

    /// An opening photo's picture is scaled to the photo's place, upscaled when smaller
    /// than the room and downscaled when larger: before its values the picture's own shape
    /// fitted to the room, from them on the place the engine renders at, which the live
    /// frame covers (decision 77). The two agree within a pixel for pictures of 1024 pixels
    /// or more; a 128 or 256 pixel thumbnail's rounded shape may step as the values come.
    #[test]
    fn an_opening_photo_s_picture_covers_the_place_its_live_frame_takes() {
        use crate::mirror::tests::photo;
        // A 6000 by 4000 photo's picture from the cache, and its camera's, larger than the
        // room.
        for (width, height) in [(1024, 683), (2048, 1365)] {
            let mut harness = places_scene(width, height);
            harness.run();
            let (before, drawn) = places(&harness);
            assert_eq!(
                drawn,
                Some(before),
                "{width} by {height}, before its values"
            );
            assert_eq!(before.width() * 2.0, 1800.0, "{width} by {height}");
            let mirror = &mut harness.state_mut().mirror;
            mirror.apply(Event::Opened(Photo {
                path: PathBuf::from("IMG_2041.ARW"),
                ..photo(2)
            }));
            mirror.apply(Event::Values(Values {
                live: false,
                extent: [6000, 4000],
                ..photo_values(0.0, 0)
            }));
            harness.run();
            let (after, drawn) = places(&harness);
            assert_eq!(drawn, Some(after), "{width} by {height}, with its values");
            assert_eq!(after.size() * 2.0, egui::vec2(1800.0, 1200.0));
            // The picture's sides are rounded, its shape the photo's to within a pixel.
            let apart = (before.size() - after.size()) * 2.0;
            assert!(
                apart.abs().max_elem() <= 1.0,
                "{width} by {height}: {apart:?}"
            );
        }
    }

    /// Where a 6000 by 4000 photo is placed in `slot`, at twice the scale with the usual
    /// margin, as `App::viewer` places it, at Small or at Fit.
    fn placed_in(slot: egui::Rect, small: bool) -> Placed {
        let block = PhotoFrame::new(slot, Margin::Points(10.0));
        let ppp = 2.0;
        let room = block.bounds() * ppp;
        let bounds = (room.x.floor() as u32, room.y.floor() as u32);
        let values = Values {
            extent: [6000, 4000],
            ..photo_values(0.0, 0)
        };
        let zoomed = zoom::Zoomed {
            scale: if small {
                zoom::Scale::Small
            } else {
                zoom::Scale::Fit
            },
            ..zoom::Zoomed::FIT
        };
        place_photo(&block, bounds, ppp, &zoomed, Some(&values), None).expect("a place")
    }

    #[test]
    fn small_centres_the_block_at_half_with_its_caption() {
        let slot = egui::Rect::from_min_size(egui::pos2(0.0, 40.0), egui::vec2(1000.0, 700.0));
        let (fit, small) = (placed_in(slot, false), placed_in(slot, true));
        // Half the fitted frame in physical pixels, an odd side rounded up.
        assert_eq!(fit.photo.size() * 2.0, egui::vec2(1960.0, 1307.0));
        assert_eq!(small.photo.size() * 2.0, egui::vec2(980.0, 654.0));
        // The block centred in the slot as at Fit, its corner on the physical pixel grid.
        let block = |p: &Placed| p.photo.union(p.caption);
        let apart = block(&small).center() - slot.center();
        assert!(apart.abs().max_elem() <= 0.5, "{apart:?}");
        let corner = small.photo.min * 2.0;
        assert_eq!(corner, corner.round());
        // The caption as wide as the smaller photo, under it.
        assert_eq!(small.caption.width(), small.photo.width());
        assert_eq!(small.caption.left(), small.photo.left());
        assert!(small.caption.top() > small.photo.bottom());
        assert_eq!(
            small.caption.top() - small.photo.bottom(),
            fit.caption.top() - fit.photo.bottom()
        );
    }

    #[test]
    fn small_and_fit_hold_through_a_resize() {
        let narrow = egui::Rect::from_min_size(egui::pos2(0.0, 40.0), egui::vec2(800.0, 700.0));
        let wide = egui::Rect::from_min_size(egui::pos2(0.0, 40.0), egui::vec2(1400.0, 700.0));
        for slot in [narrow, wide, narrow] {
            let (fit, small) = (placed_in(slot, false), placed_in(slot, true));
            // Each worked out again for the room: Fit fills it on one side, Small is half.
            let room = PhotoFrame::new(slot, Margin::Points(10.0)).bounds();
            let fills = room - fit.photo.size();
            assert!(fills.min_elem() < 0.5, "{slot:?}: {fills:?}");
            let half = (fit.photo.size() * 2.0 / 2.0).ceil() / 2.0;
            assert_eq!(small.photo.size(), half, "{slot:?}");
        }
    }

    /// A 6000 × 4000 photo in a room of 2400 × 1600 physical pixels, fitted at 40%.
    const ZOOM_ROOM: zoom::Room = zoom::Room {
        extent: [6000, 4000],
        bounds: (2400, 1600),
    };

    /// The fitted frame of [`ZOOM_ROOM`], the whole photo at 40%.
    const FITTED: FramePlace = FramePlace {
        scale: 0.4,
        origin: [0, 0],
        extent: [6000, 4000],
    };

    fn zoomed_to(scale: zoom::Scale, centre: [f32; 2]) -> zoom::Zoomed {
        zoom::Zoomed { scale, centre }
    }

    /// The physical pixels of the area, from its corner, a layer drawn as `shown` from a
    /// frame of `size` covers on each axis.
    fn covered(shown: &viewport::Shown, size: [u32; 2]) -> [std::ops::Range<f32>; 2] {
        [0, 1].map(|axis| {
            let start = -shown.source[axis] * shown.scale[axis];
            start..start + size[axis] as f32 * shown.scale[axis]
        })
    }

    /// The photo area as `App::viewer` moves and zooms it, at twice the scale: 1200 × 800
    /// points, [`ZOOM_ROOM`]'s room, at (50, 50) in the slot [`PAN_SLOT`], the zoom kept in
    /// the state, its gesture, its clock ([`wait`]) and whether a picker is on in the
    /// context's data, and the
    /// slot's right-clicks over it counted, as the photo's menu takes them. Under the slot,
    /// a Tools panel's row that takes the wheel ([`PAN_ROW`]), its value in the data too.
    fn panning(zoomed: zoom::Zoomed) -> Harness<'static, zoom::Zoomed> {
        let clock = Instant::now();
        Harness::builder()
            .with_size(egui::vec2(1300.0, 940.0))
            .with_pixels_per_point(2.0)
            .with_context_setup(|ctx| apertrust_ui::install(ctx, Theme::default()))
            .build_ui_state(
                move |ui, zoomed: &mut zoom::Zoomed| {
                    popup::show(ui.ctx());
                    let picker = ui.ctx().data(|d| d.get_temp::<bool>(PICKER_ON));
                    let drags = !picker.unwrap_or(false);
                    *zoomed = pan_photo(ui, PAN_AREA, *zoomed, &ZOOM_ROOM, drags);
                    let slot =
                        ui.interact(PAN_SLOT, egui::Id::NULL.with("slot"), egui::Sense::click());
                    if slot.secondary_clicked() {
                        ui.ctx()
                            .data_mut(|d| *d.get_temp_mut_or(egui::Id::NULL.with("menus"), 0) += 1);
                    }
                    // A picker on takes the photo's clicks and drags, as its marks do.
                    let kept = |name| egui::Id::NULL.with(name);
                    if !drags {
                        ui.interact(PAN_AREA, kept("picker"), egui::Sense::click_and_drag());
                    }
                    let mut gesture: zoom::Gesture = ui
                        .ctx()
                        .data(|d| d.get_temp(kept("gesture")))
                        .unwrap_or_default();
                    // The harness's own clock, which a test moves on.
                    let elapsed: Duration = ui
                        .ctx()
                        .data(|d| d.get_temp(kept("clock")))
                        .unwrap_or_default();
                    let now = clock + elapsed;
                    let room = &ZOOM_ROOM;
                    *zoomed = zoom_photo(ui, PAN_SLOT, PAN_AREA, *zoomed, room, &mut gesture, now);
                    ui.ctx()
                        .data_mut(|d| d.insert_temp(kept("gesture"), gesture));
                    let builder = egui::UiBuilder::new().max_rect(PAN_ROW);
                    let action = ui.scope_builder(builder, |ui| {
                        components::SliderRow::new("Exposure", row_value(ui.ctx()), -4.0..=4.0)
                            .step(0.1)
                            .wheel(components::Wheel::Pointer)
                            .show(ui)
                    });
                    if let Some(components::SliderAction::Set { value, .. }) = action.inner {
                        ui.ctx().data_mut(|d| d.insert_temp(kept("row"), value));
                    }
                },
                zoomed,
            )
    }

    /// The slot round the photo area of [`panning`], and the row under it.
    const PAN_SLOT: egui::Rect = egui::Rect {
        min: egui::pos2(0.0, 0.0),
        max: egui::pos2(1300.0, 900.0),
    };
    const PAN_ROW: egui::Rect = egui::Rect {
        min: egui::pos2(50.0, 905.0),
        max: egui::pos2(450.0, 935.0),
    };

    /// Moves [`panning`]'s clock on by `by`.
    fn wait(harness: &mut Harness<'_, zoom::Zoomed>, by: Duration) {
        let clock = egui::Id::NULL.with("clock");
        harness
            .ctx
            .data_mut(|d| *d.get_temp_mut_or_default::<Duration>(clock) += by);
    }

    /// The value of [`panning`]'s row.
    fn row_value(ctx: &egui::Context) -> f64 {
        ctx.data(|d| d.get_temp(egui::Id::NULL.with("row")))
            .unwrap_or(0.0)
    }

    #[test]
    fn a_zoomed_photo_keeps_its_right_click() {
        let mut harness = panning(zoomed_to(zoom::Scale::Factor(1.0), [0.5, 0.5]));
        harness.hover_at(PAN_AREA.center());
        harness.run();
        for pressed in [true, false] {
            harness.event(egui::Event::PointerButton {
                pos: PAN_AREA.center(),
                button: egui::PointerButton::Secondary,
                pressed,
                modifiers: Modifiers::NONE,
            });
        }
        harness.run();
        let menus = harness
            .ctx
            .data(|d| d.get_temp::<i32>(egui::Id::NULL.with("menus")));
        assert_eq!(menus, Some(1));
        // And a drag still moves the photo.
        drag(&mut harness, egui::vec2(100.0, 0.0));
        assert!(harness.state().centre[0] < 0.5);
    }

    const PAN_AREA: egui::Rect = egui::Rect {
        min: egui::pos2(50.0, 50.0),
        max: egui::pos2(1250.0, 850.0),
    };

    /// A turn of the mouse wheel by `delta` points, down positive, with `modifiers`, over
    /// the area's middle.
    fn scroll(harness: &mut Harness<'_, zoom::Zoomed>, delta: egui::Vec2, modifiers: Modifiers) {
        let unit = egui::MouseWheelUnit::Point;
        wheel_at(harness, PAN_AREA.center(), unit, delta, modifiers);
    }

    /// A turn of the mouse wheel at `at` by `delta` in `unit`s, down positive, with
    /// `modifiers`, and the frames egui spreads it over.
    fn wheel_at(
        harness: &mut Harness<'_, zoom::Zoomed>,
        at: egui::Pos2,
        unit: egui::MouseWheelUnit,
        delta: egui::Vec2,
        modifiers: Modifiers,
    ) {
        harness.hover_at(at);
        harness.run();
        harness.event_modifiers(
            egui::Event::MouseWheel {
                unit,
                delta,
                phase: egui::TouchPhase::Move,
                source: egui::MouseWheelSource::Wheel,
                modifiers,
            },
            modifiers,
        );
        harness.run_steps(12);
    }

    /// Ctrl as Windows and Linux hold it, the command modifier too.
    const CTRL: Modifiers = Modifiers {
        ctrl: true,
        command: true,
        ..Modifiers::NONE
    };

    /// The photo's point under `at` where `zoomed` shows it in [`panning`]'s area, 0 to 1
    /// across it.
    fn under(zoomed: &zoom::Zoomed, at: egui::Pos2) -> [f32; 2] {
        let placed = ZOOM_ROOM.place(zoomed);
        let d = (at - PAN_AREA.center()) * 2.0;
        let shown = placed.shown as f32;
        [0, 1].map(|axis| placed.centre[axis] + d[axis] / (ZOOM_ROOM.extent[axis] as f32 * shown))
    }

    /// Whether the photo's point under `at` is the same, within a physical pixel, at
    /// `before` and at `after`.
    fn kept_under(before: &zoom::Zoomed, after: &zoom::Zoomed, at: egui::Pos2) -> bool {
        let pixel = |axis: usize| {
            1.0 / (ZOOM_ROOM.extent[axis] as f32 * ZOOM_ROOM.place(after).shown as f32)
        };
        let (was, is) = (under(before, at), under(after, at));
        (0..2).all(|axis| (was[axis] - is[axis]).abs() < pixel(axis))
    }

    /// A click of `button` at `at`.
    fn press_at(
        harness: &mut Harness<'_, zoom::Zoomed>,
        at: egui::Pos2,
        button: egui::PointerButton,
    ) {
        harness.hover_at(at);
        harness.run();
        for pressed in [true, false] {
            harness.event(egui::Event::PointerButton {
                pos: at,
                button,
                pressed,
                modifiers: Modifiers::NONE,
            });
        }
        harness.run();
    }

    /// A point of the photo area off its middle, where a zoom about it moves the centre.
    const OFF_MIDDLE: egui::Pos2 = egui::pos2(850.0, 300.0);

    #[test]
    fn ctrl_scroll_over_the_photo_zooms_and_never_reaches_a_row() {
        let line = egui::MouseWheelUnit::Line;
        let up = egui::vec2(0.0, 1.0);
        let mut harness = panning(zoom::Zoomed::FIT);
        // A notch up at Fit, 40%: 44%, about the pointer.
        wheel_at(&mut harness, OFF_MIDDLE, line, up, CTRL);
        let notched = *harness.state();
        assert_eq!(notched.scale, zoom::Scale::Factor(0.4 * 1.1));
        assert!(
            kept_under(&zoom::Zoomed::FIT, &notched, OFF_MIDDLE),
            "{notched:?}"
        );
        assert_eq!(row_value(&harness.ctx), 0.0);
        // A notch down then up in one frame: to Fit, then 44%, in the order they came.
        let mut batched = panning(zoom::Zoomed::FIT);
        batched.hover_at(OFF_MIDDLE);
        batched.run();
        let notch = |up: f32| egui::Event::MouseWheel {
            unit: line,
            delta: egui::vec2(0.0, up),
            phase: egui::TouchPhase::Move,
            source: egui::MouseWheelSource::Wheel,
            modifiers: CTRL,
        };
        batched.input_mut().events.extend([notch(-1.0), notch(1.0)]);
        batched.run();
        assert_eq!(batched.state().scale, zoom::Scale::Factor(0.4 * 1.1));
        // Nine more stop on 100%, which reads so.
        for _ in 0..9 {
            wheel_at(&mut harness, OFF_MIDDLE, line, up, CTRL);
        }
        assert_eq!(harness.state().scale, zoom::Scale::Factor(1.0));
        assert_eq!(harness.state().label(), Zoom::Percent(100.0));
        // Over the surround it zooms about the pointer too, the edges then keeping the
        // photo in place.
        wheel_at(&mut harness, egui::pos2(20.0, 450.0), line, -up, CTRL);
        assert!(harness.state().scale != zoom::Scale::Factor(1.0));
        // Down to Fit, never past it.
        for _ in 0..12 {
            wheel_at(&mut harness, OFF_MIDDLE, line, -up, CTRL);
        }
        assert_eq!(*harness.state(), zoom::Zoomed::FIT);
        // Over the row, the row's, never the photo's.
        wheel_at(&mut harness, PAN_ROW.center(), line, up, CTRL);
        assert_eq!(*harness.state(), zoom::Zoomed::FIT);
        assert!(row_value(&harness.ctx) > 0.0);
    }

    #[test]
    fn a_pinch_zooms_about_its_centre() {
        let mut harness = panning(zoom::Zoomed::FIT);
        harness.hover_at(OFF_MIDDLE);
        harness.run();
        harness.event(egui::Event::Zoom(1.5));
        harness.run();
        let pinched = *harness.state();
        let shown = ZOOM_ROOM.place(&pinched).shown as f32;
        assert!((shown - 0.6).abs() < 1e-5, "{pinched:?}");
        assert!(
            kept_under(&zoom::Zoomed::FIT, &pinched, OFF_MIDDLE),
            "{pinched:?}"
        );
        // On within 4% of 100%: it rests there, and moves on past it.
        harness.event(egui::Event::Zoom(1.0 / 0.6 * 1.03));
        harness.run();
        assert_eq!(harness.state().scale, zoom::Scale::Factor(1.0));
        harness.event(egui::Event::Zoom(1.05));
        harness.run();
        let on = ZOOM_ROOM.place(harness.state()).shown;
        assert!((on - 1.03 * 1.05).abs() < 1e-4, "{on}");
        // Back to rest on it at 98%; a pinch after a pause starts again from 100%.
        harness.event(egui::Event::Zoom(0.98 / (1.03 * 1.05)));
        harness.run();
        assert_eq!(harness.state().scale, zoom::Scale::Factor(1.0));
        wait(&mut harness, zoom::Gesture::IDLE * 2);
        harness.event(egui::Event::Zoom(1.05));
        harness.run();
        let again = ZOOM_ROOM.place(harness.state()).shown;
        assert!((again - 1.05).abs() < 1e-4, "{again}");
        // Out, it stops at Fit.
        harness.event(egui::Event::Zoom(0.1));
        harness.run();
        assert_eq!(*harness.state(), zoom::Zoomed::FIT);
    }

    #[test]
    fn a_touch_screen_pinch_zooms_about_its_centre_and_never_pans() {
        // At 100%, two fingers either side of a point spread from 200 to 300 points apart,
        // the first one moving the pointer as egui-winit has it: 150%, the point kept. Across
        // and down, where the first finger leaves the slot for the row under it.
        let low = egui::pos2(650.0, 780.0);
        for (centre, first_way) in [(OFF_MIDDLE, egui::vec2(-1.0, 0.0)), (low, egui::Vec2::Y)] {
            let hundred = zoomed_to(zoom::Scale::Factor(1.0), [0.5, 0.5]);
            let mut harness = panning(hundred);
            let touch = |finger: u64, phase, pos| egui::Event::Touch {
                device_id: egui::TouchDeviceId(0),
                id: egui::TouchId(finger),
                phase,
                pos,
                force: None,
            };
            let (start, move_) = (egui::TouchPhase::Start, egui::TouchPhase::Move);
            let apart = |by: f32| [centre + first_way * by, centre - first_way * by];
            // Each frame's events together, as egui-winit hands them over.
            let mut frame = |events: Vec<egui::Event>| {
                harness.input_mut().events.extend(events);
                harness.step();
            };
            let [first, second] = apart(100.0);
            let press = egui::Event::PointerButton {
                pos: first,
                button: egui::PointerButton::Primary,
                pressed: true,
                modifiers: Modifiers::NONE,
            };
            frame(vec![
                egui::Event::PointerMoved(first),
                press,
                touch(0, start, first),
                touch(1, start, second),
            ]);
            frame(Vec::new());
            for by in [110.0, 125.0, 150.0] {
                let [first, second] = apart(by);
                frame(vec![
                    egui::Event::PointerMoved(first),
                    touch(0, move_, first),
                    touch(1, move_, second),
                ]);
            }
            let pinched = *harness.state();
            let shown = ZOOM_ROOM.place(&pinched).shown as f32;
            assert!((shown - 1.5).abs() < 1e-4, "{centre:?}: {pinched:?}");
            assert!(
                kept_under(&hundred, &pinched, centre),
                "{centre:?}: {pinched:?}"
            );
        }
    }

    #[test]
    fn a_windows_touchpad_pinch_arrives_as_ctrl_wheel_and_zooms() {
        // Parts of a line, each a smooth step of the zoom, never a notch of 1.1.
        let mut harness = panning(zoom::Zoomed::FIT);
        let line = egui::MouseWheelUnit::Line;
        for _ in 0..4 {
            wheel_at(&mut harness, OFF_MIDDLE, line, egui::vec2(0.0, 0.25), CTRL);
        }
        let pinched = *harness.state();
        let shown = ZOOM_ROOM.place(&pinched).shown as f32;
        let expected = 0.4 * (4.0 * 0.25 * 40.0 / 200.0_f32).exp();
        assert!((shown - expected).abs() < 1e-4, "{shown} {expected}");
        assert!(
            kept_under(&zoom::Zoomed::FIT, &pinched, OFF_MIDDLE),
            "{pinched:?}"
        );
    }

    #[test]
