        // A picker on keeps the primary button, never the middle one.
        harness.ctx.data_mut(|d| d.insert_temp(PICKER_ON, true));
        press_at(&mut harness, OFF_MIDDLE, middle);
        assert_eq!(harness.state().scale, zoom::Scale::Factor(1.0));
