    /// A drag with the primary button from the area's middle by `by` points.
    fn drag(harness: &mut Harness<'_, zoom::Zoomed>, by: egui::Vec2) {
        let from = PAN_AREA.center();
        harness.hover_at(from);
        harness.drag_at(from);
        harness.run();
        harness.hover_at(from + by);
        harness.run();
        harness.drop_at(from + by);
        harness.run();
    }

    #[test]
    fn scrolling_and_dragging_at_fit_do_nothing() {
        for fitted in [zoom::Zoomed::FIT, zoomed_to(zoom::Scale::Small, [0.5, 0.5])] {
            let mut harness = panning(fitted);
            scroll(&mut harness, egui::vec2(0.0, 40.0), Modifiers::NONE);
            drag(&mut harness, egui::vec2(120.0, 80.0));
            assert_eq!(*harness.state(), fitted);
        }
        // At 100% a scroll down shows more of the top, a drag right more of the left.
        let mut harness = panning(zoomed_to(zoom::Scale::Factor(1.0), [0.5, 0.5]));
        scroll(&mut harness, egui::vec2(0.0, 40.0), Modifiers::NONE);
        let [x, y] = harness.state().centre;
        assert_eq!(x, 0.5);
        assert!((y - (0.5 - 80.0 / 4000.0)).abs() < 1e-4, "{y}");
        drag(&mut harness, egui::vec2(120.0, 0.0));
        let [x, _] = harness.state().centre;
        assert!((x - (0.5 - 240.0 / 6000.0)).abs() < 1e-4, "{x}");
        // Shift turns the wheel sideways, once: egui's own turn, not doubled.
        let mut harness = panning(zoomed_to(zoom::Scale::Factor(1.0), [0.5, 0.5]));
        scroll(&mut harness, egui::vec2(0.0, 40.0), Modifiers::SHIFT);
        let [x, y] = harness.state().centre;
        assert_eq!(y, 0.5);
        assert!((x - (0.5 - 80.0 / 6000.0)).abs() < 1e-4, "{x}");
    }

    #[test]
    fn the_cursor_is_a_hand_over_a_zoomed_photo() {
        let cursor =
            |harness: &Harness<'_, zoom::Zoomed>| harness.output().platform_output.cursor_icon;
        let mut harness = panning(zoomed_to(zoom::Scale::Factor(1.0), [0.5, 0.5]));
        harness.hover_at(PAN_AREA.center());
        harness.run();
        assert_eq!(cursor(&harness), egui::CursorIcon::Grab);
        harness.drag_at(PAN_AREA.center());
        harness.run();
        harness.hover_at(PAN_AREA.center() + egui::vec2(20.0, 0.0));
        harness.run();
        assert_eq!(cursor(&harness), egui::CursorIcon::Grabbing);
        // At Fit and Small, the arrow.
        for fitted in [zoom::Zoomed::FIT, zoomed_to(zoom::Scale::Small, [0.5, 0.5])] {
            let mut harness = panning(fitted);
            harness.hover_at(PAN_AREA.center());
            harness.run();
            assert_eq!(cursor(&harness), egui::CursorIcon::Default);
        }
    }

    #[test]
    fn a_zoom_draws_on_the_frame_of_its_input() {
        // 400% chosen at Fit: before the session's frame for it, the fitted frame, enlarged
        // smoothly about the view's centre, covers the whole area at once.
        let zoomed = zoom::Zoomed::FIT
            .step(zoom::ZoomStep::To(zoom::Scale::Factor(4.0)), &ZOOM_ROOM)
            .expect("400%");
        let placement = ZOOM_ROOM.place(&zoomed);
        let (under, shown) = photo_layers(&FITTED, None, &placement);
        assert_eq!(under, None);
        assert_eq!(shown.filter, viewport::Filter::Smooth);
        assert_eq!(shown.scale, [10.0, 10.0]);
        let area = area_size(&placement, ZOOM_ROOM.bounds);
        assert_eq!(area, egui::vec2(2400.0, 1600.0));
        let [across, down] = covered(&shown, [2400, 1600]);
        assert!(across.start <= 0.0 && across.end >= area.x, "{across:?}");
        assert!(down.start <= 0.0 && down.end >= area.y, "{down:?}");
        // Its middle frame pixel under the area's middle.
        let middle = [0, 1].map(|axis| shown.source[axis] + area[axis] / 2.0 / shown.scale[axis]);
        assert_eq!(middle, [1200.0, 800.0]);
        // The session's frame for it, the detail at 100%, then in squares, from 200%.
        let detail = FramePlace {
            scale: 1.0,
            origin: [2700, 1800],
            extent: [6000, 4000],
        };
        let (under, shown) = photo_layers(&detail, Some([2400, 1600]), &placement);
        assert_eq!(shown.filter, viewport::Filter::Nearest);
        assert_eq!(
            under.map(|under| under.filter),
            Some(viewport::Filter::Smooth)
        );
    }

    #[test]
    fn a_pan_never_shows_the_surround_inside_an_overflowing_axis() {
        // At 100%, the detail of the view's centre with its overview, panned step by step
        // to each edge: the overview always covers the whole area, the detail where it
        // reaches.
        let mut zoomed = zoomed_to(zoom::Scale::Factor(1.0), [0.5, 0.5]);
        let detail = FramePlace {
            scale: 1.0,
            origin: [1800, 1200],
            extent: [6000, 4000],
        };
        let steps = [
            egui::vec2(700.0, 0.0),
            egui::vec2(-1500.0, 300.0),
            egui::vec2(-3000.0, -3000.0),
            egui::vec2(5000.0, 5000.0),
        ];
        for step in steps {
            for _ in 0..4 {
                zoomed = zoomed.panned(step, &ZOOM_ROOM);
                let placement = ZOOM_ROOM.place(&zoomed);
                let area = area_size(&placement, ZOOM_ROOM.bounds);
                let (under, _) = photo_layers(&detail, Some([2400, 1600]), &placement);
                let under = under.expect("the overview");
                let [across, down] = covered(&under, [2400, 1600]);
                let close = |a: f32, b: f32| (a - b).abs() < 1e-2;
                assert!(
                    across.start <= 0.0 || close(across.start, 0.0),
                    "{zoomed:?}"
                );
                assert!(down.start <= 0.0 || close(down.start, 0.0), "{zoomed:?}");
                assert!(
                    across.end >= area.x || close(across.end, area.x),
                    "{zoomed:?}"
                );
                assert!(down.end >= area.y || close(down.end, area.y), "{zoomed:?}");
            }
        }
    }

    #[test]
    fn a_resize_at_200_keeps_the_centre() {
        let zoomed = zoomed_to(zoom::Scale::Factor(2.0), [0.3, 0.6]);
        for bounds in [(2400, 1600), (3000, 1800), (1200, 900)] {
            let room = zoom::Room {
                extent: [6000, 4000],
                bounds,
            };
            let placement = room.place(&zoomed);
            assert_eq!(placement.shown, 2.0, "{bounds:?}");
            assert_eq!(placement.centre, [0.3, 0.6], "{bounds:?}");
            let area = area_size(&placement, bounds);
            assert_eq!(area, egui::vec2(bounds.0 as f32, bounds.1 as f32));
        }
        // A centre near the edge is kept inside it again as the room grows.
        let near = zoomed_to(zoom::Scale::Factor(2.0), [0.05, 0.6]);
        let wide = zoom::Room {
            extent: [6000, 4000],
            bounds: (3000, 1800),
        };
        assert_eq!(wide.place(&near).centre[0], 3000.0 / (2.0 * 6000.0 * 2.0));
    }

    #[test]
    fn rendering_shows_after_a_second_and_not_before() {
        let room = Some(&ZOOM_ROOM);
        let sent = Instant::now();
        let hundred = zoomed_to(zoom::Scale::Factor(1.0), [0.5, 0.5]);
        let fit = Some(ZOOM_ROOM.place(&zoom::Zoomed::FIT));
        let mut pending = Some((7, sent, hundred.view()));
        // Not yet: a frame asked for then.
        let half = sent + Duration::from_millis(500);
        assert_eq!(
            view_rendering(&mut pending, Some((6, fit)), room, half),
            (false, Some(Duration::from_millis(500)))
        );
        // A second on, still not told: Rendering.
        let later = sent + mirror::RENDERING_AFTER;
        let told = Some((6, fit));
        assert_eq!(
            view_rendering(&mut pending, told, room, later),
            (true, None)
        );
        // Told a view through it, its frame with it: gone, and let go.
        let told = Some((7, Some(ZOOM_ROOM.place(&hundred))));
        assert_eq!(
            view_rendering(&mut pending, told, room, later),
            (false, None)
        );
        assert_eq!(pending, None);
        // Nothing on its way, nothing said.
        assert_eq!(view_rendering(&mut None, None, room, later), (false, None));
        // A view the session holds already, as after 100% and Fit in one batch at Fit,
        // which tells nothing: nothing on its way.
        let mut pending = Some((9, sent, zoom::Zoomed::FIT.view()));
        assert_eq!(
            view_rendering(&mut pending, Some((6, fit)), room, later),
            (false, None)
        );
        assert_eq!(pending, None);
    }

    #[test]
    fn rendering_ends_when_the_session_clamps_to_the_view_it_shows() {
        // At 100% panned to the left edge, the room widened: the session placed the photo
        // at its clamped centre before the view sent again came, which then tells nothing.
        let room = zoom::Room {
            extent: [6000, 4000],
            bounds: (3000, 1600),
        };
        let asked = zoomed_to(zoom::Scale::Factor(1.0), [0.2, 0.5]);
        let held = zoomed_to(zoom::Scale::Factor(1.0), [0.25, 0.5]);
        let told = Some((6, Some(room.place(&held))));
        let sent = Instant::now();
        let mut pending = Some((9, sent, asked.view()));
        let later = sent + mirror::RENDERING_AFTER;
        assert_eq!(
            view_rendering(&mut pending, told, Some(&room), later),
            (false, None)
        );
        assert_eq!(pending, None);
        // A view the session has not taken yet waits.
        let mut pending = Some((
            9,
            sent,
            zoomed_to(zoom::Scale::Factor(2.0), [0.2, 0.5]).view(),
        ));
        assert_eq!(
            view_rendering(&mut pending, told, Some(&room), later),
            (true, None)
        );
    }

    /// Where the panning harness keeps whether a picker is on.
    const PICKER_ON: egui::Id = egui::Id::NULL;

    #[test]
    fn a_picker_on_takes_the_drag_never_the_scroll() {
        let mut harness = panning(zoomed_to(zoom::Scale::Factor(1.0), [0.5, 0.5]));
        harness.ctx.data_mut(|d| d.insert_temp(PICKER_ON, true));
        drag(&mut harness, egui::vec2(120.0, 0.0));
        assert_eq!(harness.state().centre, [0.5, 0.5]);
        scroll(&mut harness, egui::vec2(0.0, 40.0), Modifiers::NONE);
        assert!(harness.state().centre[1] < 0.5);
    }

    #[test]
    fn the_photo_area_and_the_whole_photo_follow_the_zoom() {
        let ppp = 2.0;
        let area = egui::Rect::from_min_size(egui::pos2(10.0, 20.0), egui::vec2(1200.0, 800.0));
        // At Fit the area is the whole photo.
        let fit = ZOOM_ROOM.place(&zoom::Zoomed::FIT);
        assert_eq!(
            area_size(&fit, ZOOM_ROOM.bounds),
            egui::vec2(2400.0, 1600.0)
        );
        assert_eq!(whole_photo(area, &fit, ppp), area);
        // At 100% centred, 6000 × 4000 physical pixels, the area 1800 × 1200 into it.
        let hundred = ZOOM_ROOM.place(&zoomed_to(zoom::Scale::Factor(1.0), [0.5, 0.5]));
        let whole = whole_photo(area, &hundred, ppp);
        assert_eq!(whole.size(), egui::vec2(3000.0, 2000.0));
        assert_eq!(area.min - whole.min, egui::vec2(900.0, 600.0));
        // A photo smaller than the room on one axis at Fill: centred on it.
        let room = zoom::Room {
            extent: [6000, 4000],
            bounds: (1000, 1000),
        };
        let fill = room.place(&zoomed_to(zoom::Scale::Fill, [0.5, 0.5]));
        assert_eq!(area_size(&fill, room.bounds), egui::vec2(1000.0, 1000.0));
        let small = room.place(&zoomed_to(zoom::Scale::Factor(0.1), [0.5, 0.5]));
        assert_eq!(area_size(&small, room.bounds), egui::vec2(1000.0, 667.0));
    }

    /// A photo whose edit crops it to another shape than its picture's: from its values on,
    /// the picture is letterboxed inside the place the live frame covers, centred and
    /// smaller than it on one side, never stretched to it (decision 77).
    #[test]
    fn an_opening_photo_s_picture_of_another_shape_is_letterboxed_in_its_place() {
        use crate::mirror::tests::photo;
        for (width, height) in [(1024, 683), (2048, 1365)] {
            let mut harness = places_scene(width, height);
            let mirror = &mut harness.state_mut().mirror;
            mirror.apply(Event::Opened(Photo {
                path: PathBuf::from("IMG_2041.ARW"),
                ..photo(2)
            }));
            // A square crop of the 3:2 photo.
            mirror.apply(Event::Values(Values {
                live: false,
                extent: [4000, 4000],
                ..photo_values(0.0, 0)
            }));
            harness.run();
            let (place, drawn) = places(&harness);
            let drawn = drawn.expect("the picture drawn");
            assert!(
                (place.width() - place.height()).abs() * 2.0 <= 1.0,
                "{place:?}"
            );
            assert!(place.contains_rect(drawn), "{drawn:?} in {place:?}");
            assert_eq!(drawn.width(), place.width(), "{width} by {height}");
            assert!(drawn.height() < place.height(), "{width} by {height}");
            let off = (drawn.center() - place.center()) * 2.0;
            assert!(off.abs().max_elem() <= 1.0, "{width} by {height}: {off:?}");
            // Its own shape, within a pixel.
            let shape = drawn.width() / drawn.height();
            assert!(
                (shape - width as f32 / height as f32).abs() < 0.01,
                "{width} by {height}: {shape}"
            );
        }
    }

    #[test]
    fn while_the_next_photo_opens_the_panel_draws_no_photo_until_its_values_arrive() {
        use crate::mirror::tests::photo;
        let report = photo_values;
        let folder = settings::testing::Folder::new("panel-switch");
        let mut harness = editing(&folder);
        let mirror = &mut harness.state_mut().mirror;
        mirror.apply(Event::Opened(photo(1)));
        mirror.apply(Event::Values(report(1.5, 1)));
        mirror.apply(Event::Scopes(scopes::testing::reading(true, false, false)));
        harness.run();
        assert_eq!(
            exposure_slider(&harness),
            (String::from("+1.500 EV"), false)
        );
        harness.get_by_role_and_label(Role::Button, "Scopes");
        // Another photo is asked for: every frame from the next until its values arrive
        // draws no photo, never a panel without sections.
        harness
            .state_mut()
            .mirror
            .opening(PathBuf::from("/photos/b.ARW"), 2, Instant::now());
        for step in 0..3 {
            if step == 1 {
                harness.state_mut().mirror.apply(Event::Opened(photo(2)));
            }
            harness.run();
            draws_no_photo(&harness, ADJUST);
            assert_eq!(exposure_slider(&harness), (String::from("+0.000 EV"), true));
        }
        // Its values arrive: the next frame is the next photo's, Scopes with it.
        harness
            .state_mut()
            .mirror
            .apply(Event::Values(report(0.5, 2)));
        harness.run();
        assert_eq!(
            exposure_slider(&harness),
            (String::from("+0.500 EV"), false)
        );
        assert_eq!(graph_says_in(&harness, "Histogram"), "Nothing measured yet");
        // Every tab's sections, live, keep ids of their own: the Effects tab's three among
        // them, whose sliders share names.
        for tab in (ADJUST + 1..HISTORY).filter(|tab| default_enabled()[*tab]) {
            harness.state_mut().shell.panel_tab = tab;
            harness.run();
            for title in titles(tab) {
                harness.get_by_role_and_label(Role::Button, &title);
            }
        }
    }

    /// What the scopes' graph, `name`, says to screen readers, in the editing tab.
    fn graph_says_in(harness: &Harness<'_, Editing>, name: &str) -> String {
        let graph = harness.get_by_role_and_label(Role::Image, name);
        let said = graph.accesskit_node().description();
        said.unwrap_or_default().to_owned()
    }

    #[test]
    fn scopes_are_pinned_over_the_adjust_tab_s_tools_and_count_the_histogram() {
        let folder = settings::testing::Folder::new("scopes-pinned");
        let mut harness = side(&folder);
        harness.run();
        assert_eq!(harness.state().shell.panel_tab, ADJUST);
        let scopes = harness.get_by_role_and_label(Role::Button, "Scopes").rect();
        let exposure = harness
            .get_by_role_and_label(Role::Button, "Exposure")
            .rect();
        let graph = harness
            .get_by_role_and_label(Role::Image, "Histogram")
            .rect();
        assert!(
            scopes.bottom() <= graph.top() && graph.bottom() <= exposure.top(),
            "Scopes {scopes:?}, its graph {graph:?}, Exposure {exposure:?}"
        );
        assert_eq!(graph_says(&harness, "Histogram"), "Nothing measured yet");
        // Every graph can be chosen; the overlays wait for the app to draw them.
        let vectorscope = harness.get_by_role_and_label(Role::RadioButton, "Vectorscope");
        assert!(!vectorscope.accesskit_node().is_disabled());
        for name in ["Show shadow clipping", "Show highlight clipping"] {
            let control = harness.get_by_label(name).accesskit_node();
            assert!(control.is_disabled(), "{name}");
        }
        assert_eq!(harness.state().sent, [counted(true, false, false)]);
        // Every editing tab pins it.
        harness.get_by_role_and_label(Role::Tab, "Geometry").click();
        harness.run();
        assert_eq!(harness.state().shell.panel_tab, 3);
        harness.get_by_role_and_label(Role::Button, "Scopes");
        assert_eq!(harness.state().sent, [counted(true, false, false)]);
    }

    #[test]
    fn the_latest_reading_reaches_the_scopes() {
        let folder = settings::testing::Folder::new("scopes-reading");
        let mut harness = side(&folder);
        harness.run();
        let reading = scopes::testing::reading(true, false, false);
        harness.state_mut().mirror.scopes.receive(&reading);
        harness.run();
        assert_eq!(
            graph_says(&harness, "Histogram"),
            "Shadows clipped: 0.01%, highlights clipped: 5%"
        );
        // The waveform chosen, the reading in hand has none until the next arrives.
        harness
            .get_by_role_and_label(Role::RadioButton, "Waveform")
            .click();
        harness.run();
        assert_eq!(graph_says(&harness, "Waveform"), "Nothing measured yet");
        let reading = scopes::testing::reading(false, true, false);
        harness.state_mut().mirror.scopes.receive(&reading);
        harness.run();
        assert_eq!(
            graph_says(&harness, "Waveform"),
            "Shadows clipped: 0.01%, highlights clipped: 5%"
        );
        // A photo closing takes its reading with it.
        harness.state_mut().mirror.scopes.forget();
        harness.run();
        assert_eq!(graph_says(&harness, "Waveform"), "Nothing measured yet");
    }

    #[test]
    fn the_scopes_ask_again_as_the_graph_changes_and_the_section_opens_and_closes() {
        let folder = settings::testing::Folder::new("scopes-asking");
        let mut harness = side(&folder);
        harness.run();
        let sent = |harness: &Harness<'_, Side>| harness.state().sent.clone();
        assert_eq!(sent(&harness), [counted(true, false, false)]);
        // The waveform's counts serve the RGB parade too.
        for graph in ["Waveform", "RGB parade"] {
            harness
                .get_by_role_and_label(Role::RadioButton, graph)
                .click();
            harness.run();
        }
        assert_eq!(
            sent(&harness),
            [counted(true, false, false), counted(false, true, false)]
        );
        // Closed, the totals alone; open again, the graph shown.
        let graph = |harness: &Harness<'_, Side>| {
            let parade = harness.query_by_role_and_label(Role::Image, "RGB parade");
            parade.is_some()
        };
        for open in [false, true] {
            harness
                .get_by_role_and_label(Role::Button, "Scopes")
                .click();
            harness.run();
            assert_eq!(graph(&harness), open);
        }
        assert_eq!(
            sent(&harness),
            [
                counted(true, false, false),
                counted(false, true, false),
                counted(false, false, false),
                counted(false, true, false)
            ]
        );
    }

    #[test]
    fn the_vectorscope_is_counted_while_it_is_chosen_and_open_and_shown_on_the_next_run() {
        let folder = settings::testing::Folder::new("scopes-vectorscope");
        let mut harness = side(&folder);
        harness.run();
        harness
            .get_by_role_and_label(Role::RadioButton, "Vectorscope")
            .click();
        harness.run();
        let sent = |harness: &Harness<'_, Side>| harness.state().sent.clone();
        let vectorscope = counted(false, false, true);
        assert_eq!(
            sent(&harness),
            [counted(true, false, false), vectorscope.clone()]
        );
        // Closed, the totals alone; open again, the vectorscope.
        for _ in 0..2 {
            harness
                .get_by_role_and_label(Role::Button, "Scopes")
                .click();
            harness.run();
        }
        assert_eq!(
            sent(&harness)[2..],
            [counted(false, false, false), vectorscope.clone()]
        );
        // Kept in settings, the next run shows it and asks for it from the start.
        harness.state_mut().keeper.flush();
        drop(harness);
        let mut harness = side(&folder);
        harness.run();
        harness.get_by_role_and_label(Role::Image, "Vectorscope");
        assert_eq!(sent(&harness), [vectorscope]);
    }

    #[test]
    fn a_reading_with_the_vectorscope_reaches_its_graph() {
        let folder = settings::testing::Folder::new("scopes-vectorscope-reading");
        let mut harness = side(&folder);
        harness.run();
        harness
            .get_by_role_and_label(Role::RadioButton, "Vectorscope")
            .click();
        harness.run();
        // The vectorscope's counts, as a texture as tall as the graph.
        let drawn = |harness: &Harness<'_, Side>| {
            harness.output().shapes.iter().any(|clipped| {
                matches!(&clipped.shape, egui::Shape::Mesh(mesh)
                    if mesh.texture_id != egui::TextureId::default()
                        && mesh.calc_bounds().height() > 100.0)
            })
        };
        // A reading without it, as one counted before it was chosen, measures nothing.
        let histogram = scopes::testing::reading(true, false, false);
        harness.state_mut().mirror.scopes.receive(&histogram);
        harness.run();
        assert_eq!(graph_says(&harness, "Vectorscope"), "Nothing measured yet");
        assert!(!drawn(&harness));
        let reading = scopes::testing::reading(false, false, true);
        harness.state_mut().mirror.scopes.receive(&reading);
        harness.run();
        assert_eq!(
            graph_says(&harness, "Vectorscope"),
            "Shadows clipped: 0.01%, highlights clipped: 5%"
        );
        assert!(drawn(&harness));
    }

    #[test]
    fn the_browser_bar_s_choices_change_the_grid_and_survive_a_new_shell() {
        use apertrust_ui::components::{Sort, SortKey, ThumbnailSize};
        let folder = settings::testing::Folder::new("grid-kept");
        let (mut keeper, settings) = Keeper::open(folder.storage());
        let ctx = egui::Context::default();
        let mut shell = Shell::new(&settings, Locale::EnGb, OperatingSystem::Mac);
        // With no photos in the Browser its items rest.
        let resting = shell.state(&ctx, false, false);
        assert!(shell.run(ActionId::SORT[1], &resting, &ctx, &[]).is_none());
        assert_eq!(shell.browser, settings::BrowserSettings::default());
        let shown = State {
            shown: true,
            ..resting
        };
        for id in [
            ActionId::SORT[1],
            ActionId::SORT_DESCENDING,
            ActionId::THUMBNAILS[3],
            // The browser bar's Labels, which turns the captions off.
            ActionId::SHOW_LABELS,
            // Not built: Rating changes nothing.
            ActionId::SORT[3],
        ] {
            shell.run(id, &shown, &ctx, &[]);
        }
        let chosen = settings::BrowserSettings {
            sort: Sort {
                key: SortKey::FileName,
                descending: true,
            },
            thumbnails: ThumbnailSize::ExtraLarge,
            labels: false,
            ..settings::BrowserSettings::default()
        };
        assert_eq!(shell.browser, chosen);
        // The menus check what the Browser's settings hold.
        let state = State {
            shown: true,
            ..shell.state(&ctx, false, false)
        };
        let checked = |id| actions::action(id).and_then(|a| a.checked(&state));
        assert_eq!(checked(ActionId::SORT[1]), Some(true));
        assert_eq!(checked(ActionId::SORT[0]), Some(false));
        assert_eq!(checked(ActionId::SORT_DESCENDING), Some(true));
        assert_eq!(checked(ActionId::THUMBNAILS[1]), Some(false));
        assert_eq!(checked(ActionId::SHOW_LABELS), Some(false));
        // The app ends, and starts again.
        keeper.frame(std::time::Instant::now(), &shell.to_settings(&ctx));
        keeper.flush();
        let (_, settings) = Keeper::open(folder.storage());
        assert_eq!(settings.browser, chosen);
        assert_eq!(
            Shell::new(&settings, Locale::EnGb, OperatingSystem::Mac).browser,
            chosen
        );
    }

    /// A frame as the app's: the Viewer's menus read over the whole window, the
    /// photo at `photo` if any, a picker on while `picking`, and the frame's popups drawn
    /// after it. The photo is open with an edit Reset can take back.
    struct Surround {
        shell: Shell,
        photo: Option<egui::Rect>,
        picking: bool,
        chosen: Vec<ActionId>,
    }

    /// [`Surround`] in a window of 600 × 400 points.
    fn surround(photo: Option<egui::Rect>, picking: bool) -> Harness<'static, Surround> {
        Harness::builder()
            .with_size(egui::vec2(600.0, 400.0))
            .with_os(OperatingSystem::Nix)
            .with_context_setup(|ctx| {
                apertrust_ui::install(ctx, Theme::default());
                registry_keys_only(ctx);
            })
            .build_ui_state(
                |ui, surround: &mut Surround| {
                    let ctx = ui.ctx().clone();
                    let slot = ui.allocate_rect(ui.max_rect(), egui::Sense::click());
                    let shell = &surround.shell;
                    let (photo, picking) = (surround.photo, surround.picking);
                    let state = State {
                        editable: photo.is_some(),
                        ..shell.state(&ctx, photo.is_some(), photo.is_some())
                    };
                    // At Fit the photo area is the whole photo.
                    let photo = photo.map(|photo| (photo, photo));
                    let chosen =
                        central_menu(&ctx, &slot, photo, picking, &shell.keymap, &state, None);
                    surround.chosen.extend(chosen);
                    popup::show(&ctx);
                },
                Surround {
                    shell: Shell::new(&Settings::default(), Locale::EnGb, OperatingSystem::Nix),
                    photo,
                    picking,
                    chosen: Vec::new(),
                },
            )
    }

    /// A right-click at `at`, in frames of its own.
    fn right_click_at<T>(harness: &mut Harness<'_, T>, at: egui::Pos2) {
        harness.hover_at(at);
        harness.run();
        for pressed in [true, false] {
            harness.event(egui::Event::PointerButton {
                pos: at,
                button: egui::PointerButton::Secondary,
                pressed,
                modifiers: Modifiers::NONE,
            });
        }
        harness.run();
    }

    #[test]
    fn the_surround_s_drawn_menu_gives_the_background_chosen_in_it() {
        let mut harness = surround(None, false);
        right_click_at(&mut harness, egui::pos2(300.0, 200.0));
        harness
            .get_by_role_and_label(Role::MenuItemCheckBox, "White")
            .click();
        harness.run();
        assert_eq!(harness.state().chosen, [ActionId::BACKGROUND[5]]);
    }

    /// Decision 91: a right-click on the photo opens the photo's menu, drawn: History's
    /// Reset, which a choice runs, then Export… and Background ▸; round it, the surround's
    /// Background menu, as before.
    #[test]
    fn a_right_click_on_the_photo_opens_its_menu_reset_export_background() {
        let photo = egui::Rect::from_min_size(egui::pos2(100.0, 50.0), egui::vec2(400.0, 300.0));
        let mut harness = surround(Some(photo), false);
        right_click_at(&mut harness, photo.center());
        let menu = harness.get_by_role_and_label(Role::Menu, "Photo");
        let items: Vec<String> = menu
            .query_all(egui_kittest::kittest::by().predicate(|node| {
                matches!(
                    node.role(),
                    Role::MenuItem | Role::MenuItemCheckBox | Role::MenuItemRadio
                )
            }))
            .filter_map(|node| node.accesskit_node().label())
            .collect();
        assert_eq!(items, ["Reset", "Export…", "Background", "Orientation"]);
        harness.get_by_label("Reset").click();
        harness.run();
        assert_eq!(harness.state().chosen, [ActionId::RESET]);
        // Round the photo, the surround's.
        right_click_at(&mut harness, egui::pos2(50.0, 200.0));
        assert!(
            harness
                .query_by_role_and_label(Role::Menu, "Photo")
                .is_none()
        );
        assert!(
            harness
                .query_by_role_and_label(Role::Menu, "Background")
                .is_some()
        );
    }

    /// Decision 91: Orientation ▸ in the photo's menu holds its buttons, and choosing one
    /// chooses its registry action, which runs as the button does.
