    /// Ctrl+E (Cmd+E on the Mac) reveals the Export tool from another tab: it chooses the
    /// Photos tab, opens the section and scrolls it into view, and opens no dialog.
    #[test]
    fn ctrl_e_reveals_the_export_tool_from_another_tab() {
        for (os, modifiers) in [
            (OperatingSystem::Mac, Modifiers::COMMAND),
            (OperatingSystem::Windows, Modifiers::COMMAND),
            (OperatingSystem::Nix, Modifiers::COMMAND),
        ] {
            let mut harness = bench(os);
            harness.run();
            assert_eq!(harness.state().shell.panel_tab, ADJUST, "{os:?}");
            assert!(harness.query_by_label("Export 1 photo").is_none());
            harness.key_press_modifiers(modifiers, Key::E);
            harness.run_steps(4);
            let state = harness.state();
            assert_eq!(state.pressed, [ActionId::EXPORT], "{os:?}");
            assert_eq!(state.shell.panel_tab, PHOTOS, "{os:?}");
            assert!(
                state.shell.section_open(&export::definition().tool),
                "{os:?}"
            );
            assert_eq!(state.shell.reveal, None, "{os:?}: scrolled to once");
            assert!(state.host.0.borrow().shown.is_none(), "{os:?}: no dialog");
            // Its header is scrolled to the top of the panel, Collections' above it, out of
            // view.
            let header = harness.get_by_role_and_label(Role::Button, "Export").rect();
            let tabs = harness.get_by_role_and_label(Role::Tab, "Photos").rect();
            let collections = harness
                .get_by_role_and_label(Role::Button, "Collections")
                .rect();
            assert!(
                header.top() < tabs.bottom() + 40.0,
                "{os:?} {header:?} {tabs:?}"
            );
            assert!(collections.bottom() <= header.top(), "{os:?}");
        }
    }

    /// Ctrl+E's reveal leaves the focus on the Export button, so Return exports; Esc gives
    /// it back. Ctrl+Shift+E (Cmd+Shift+E) runs Export Again, its key shown in File.
    #[test]
    fn ctrl_e_focuses_the_export_button_and_ctrl_shift_e_runs_export_again() {
        for os in [
            OperatingSystem::Mac,
            OperatingSystem::Windows,
            OperatingSystem::Nix,
        ] {
            let mut harness = bench(os);
            harness.run();
            harness.key_press_modifiers(Modifiers::COMMAND, Key::E);
            harness.run_steps(4);
            let button = harness.get_by_role_and_label(Role::Button, "Export 1 photo");
            assert!(button.is_focused(), "{os:?}");
            harness.key_press(Key::Escape);
            harness.run_steps(4);
            assert_eq!(harness.ctx.memory(|m| m.focused()), None, "{os:?}");
            harness.key_press_modifiers(Modifiers::COMMAND | Modifiers::SHIFT, Key::E);
            harness.run_steps(4);
            let state = harness.state();
            assert_eq!(
                state.pressed.last(),
                Some(&ActionId::EXPORT_AGAIN),
                "{os:?}"
            );
            assert!(state.shell.export_again, "{os:?}");
        }
        let mut harness = bench(OperatingSystem::Nix);
        harness.run();
        alt(&mut harness, Key::F, Some("f"));
        let item = harness.get_by_role_and_label(Role::MenuItem, "Export Again");
        assert_eq!(
            item.accesskit_node().data().keyboard_shortcut(),
            Some("Ctrl+Shift+E")
        );
    }

